"use client";

import { OrbitControls, PerspectiveCamera } from "@react-three/drei";
import { Canvas, useFrame } from "@react-three/fiber";
import React, { Suspense, useRef } from "react";
import * as THREE from "three";
import Ribbon from "./Ribbon";
import { scrollVelocityRef } from "./scrollState";
import { useResponsiveCamera } from "./useResponsiveCamera";
import { useRibbons } from "./useRibbons";

function ScrollManager() {
  useFrame(() => {
    // Decay scroll velocity
    scrollVelocityRef.current = THREE.MathUtils.lerp(
      scrollVelocityRef.current,
      0,
      0.05
    );
  });

  React.useEffect(() => {
    const handleWheel = (e: WheelEvent) => {
      // Prevent native page scroll
      e.preventDefault();

      // Accumulate velocity based on wheel delta
      // Increased sensitivity for snappier response
      const sensitivity = 0.2;
      scrollVelocityRef.current += e.deltaY * sensitivity;
      // Clamp max speed if needed
      scrollVelocityRef.current = THREE.MathUtils.clamp(
        scrollVelocityRef.current,
        -5,
        5
      );
    };

    window.addEventListener("wheel", handleWheel, { passive: false });
    return () => window.removeEventListener("wheel", handleWheel);
  }, []);

  return null;
}

function InteractivityLayer({ children }: { children: React.ReactNode }) {
  const groupRef = useRef<THREE.Group>(null);
  const mouse = useRef(new THREE.Vector2(0, 0));

  useFrame((state) => {
    if (groupRef.current) {
      mouse.current.x = THREE.MathUtils.lerp(
        mouse.current.x,
        state.mouse.x,
        0.02
      );
      mouse.current.y = THREE.MathUtils.lerp(
        mouse.current.y,
        state.mouse.y,
        0.02
      );

      groupRef.current.rotation.y = mouse.current.x * 0.12;
      groupRef.current.rotation.x = -mouse.current.y * 0.08;
    }
  });

  return <group ref={groupRef}>{children}</group>;
}

function Scene() {
  const ribbons = useRibbons();
  useResponsiveCamera(); // Handle camera responsiveness

  return (
    <>
      <ScrollManager />
      <PerspectiveCamera fov={65} makeDefault position={[0, 0, 32]} />
      <color args={["#fff9c4"]} attach="background" />

      <ambientLight color="#fffcf0" intensity={2} />
      <spotLight
        angle={0.3}
        castShadow
        color="#ffffff"
        intensity={20}
        penumbra={1}
        position={[50, 100, 50]}
      />
      <pointLight color="#fff1f1" intensity={6.0} position={[-40, 20, 20]} />

      <InteractivityLayer>
        <group rotation={[-0.15, -0.4, 0.02]}>
          {ribbons.map((ribbon, i) => (
            <Ribbon key={i} {...ribbon} />
          ))}
        </group>
      </InteractivityLayer>

      <OrbitControls enablePan={false} enableZoom={false} />
    </>
  );
}

export default function NotFound404() {
  return (
    <div className="relative h-screen w-full overflow-hidden bg-[#fff9c4] font-sans">
      <Canvas
        dpr={[1, 2]}
        gl={{ antialias: true, stencil: false, depth: true }}
      >
        <Suspense fallback={null}>
          <Scene />
        </Suspense>
      </Canvas>

      <div className="pointer-events-none absolute inset-0 z-10 flex select-none items-center justify-center overflow-hidden">
        <span className="translate-y-[-5%] font-black text-[45vw] text-black/3 leading-none tracking-tighter">
          404
        </span>
      </div>
    </div>
  );
}

import { useFrame } from "@react-three/fiber";
import React, { useMemo, useRef } from "react";
import * as THREE from "three";
import { RIBBON_TEXT_SPEED_MULTIPLIER } from "./constants";
import { fragmentShader, vertexShader } from "./ribbonShader";
import { scrollVelocityRef } from "./scrollState";
import type { RibbonProps } from "./types";
import { useCachedTexture } from "./useCachedTexture";
import { useFontsReady } from "./useFontsReady";
import {
  generateBackTexture,
  generateFrontTexture,
} from "./utils/textureGenerators";

// 1x1 pixel transparent texture for safe initialization
const DATA_ONE_PIXEL = new Uint8Array([0, 0, 0, 0]);
const EMPTY_TEXTURE = new THREE.DataTexture(
  DATA_ONE_PIXEL,
  1,
  1,
  THREE.RGBAFormat
);
EMPTY_TEXTURE.needsUpdate = true;

const Ribbon = function Ribbon({
  text,
  position,
  rotation,
  color,
  width = 10,
  height = 1.5,
  thickness = 0.5,
  speed = 1.0,
  frequency = 0.5,
  amplitude = 0.3,
  padding = 40,
  subscript = "",
  backsideText = "",
  backsideImage = null,
  backOffset = [0, 0],
  backScale = [1, 1],
  backClamp = 0.0,
  textSpeed = 0.2,
}: RibbonProps) {
  const meshRef = useRef<THREE.Mesh>(null);
  const materialRef = useRef<THREE.ShaderMaterial>(null);
  const fontsReady = useFontsReady();

  // Generate unique key for front texture
  // NOTE: Color removed from key as it is now applied in shader
  const frontTextureKey = `front_${text}_${subscript}_NOCOLOR_${width}_${height}_${fontsReady}`;

  const texture = useCachedTexture(frontTextureKey, () =>
    generateFrontTexture({
      text,
      subscript,
      color: "transparent", // Only used for unused invalidation, essentially ignored by new generator
      width,
      height,
      padding,
      fontsReady,
    })
  );

  // Generate unique key for back texture
  const backTextureKey = backsideImage
    ? null
    : `back_${backsideText || "DEFAULT"}_NOCOLOR_${width}_${height}_${fontsReady}`;

  const generatedBackTexture = useCachedTexture(backTextureKey || "", () =>
    generateBackTexture({
      text: backsideText,
      color,
      width,
      height,
      fontsReady,
    })
  );

  const finalBacksideTexture = backsideImage || generatedBackTexture;

  // STABLE UNIFORMS: Created once via useMemo, values updated imperatively
  const uniforms = useMemo(
    () => ({
      uTime: { value: 0 },
      uTexture: { value: EMPTY_TEXTURE as THREE.Texture },
      uBackTexture: { value: EMPTY_TEXTURE as THREE.Texture },
      uBackOffset: { value: new THREE.Vector2(0, 0) },
      uBackScale: { value: new THREE.Vector2(1, 1) },
      uBackClamp: { value: 0 },
      uColor: { value: new THREE.Color(color) },
      uFrequency: { value: frequency },
      uAmplitude: { value: amplitude },
      uOpacity: { value: 1.0 },
      uTextSpeed: { value: textSpeed },
      uRunTime: { value: 0 },
      uRepeat: { value: new THREE.Vector2(1, 1) },
      uBackRepeat: { value: new THREE.Vector2(1, 1) },
    }),
    [amplitude, color, frequency, textSpeed]
  ); // Empty deps = created once and stable forever

  // Update uniforms when props change
  // This avoids recreating the uniforms object which can reset the material
  React.useLayoutEffect(() => {
    uniforms.uBackOffset.value.set(backOffset[0], backOffset[1]);
    uniforms.uBackScale.value.set(backScale[0], backScale[1]);
    uniforms.uBackClamp.value = backClamp;
    uniforms.uColor.value.set(color);
    uniforms.uFrequency.value = frequency;
    uniforms.uAmplitude.value = amplitude;
    uniforms.uTextSpeed.value = textSpeed * RIBBON_TEXT_SPEED_MULTIPLIER;

    if (texture) {
      uniforms.uTexture.value = texture;
      uniforms.uRepeat.value.copy(texture.repeat);
    }

    if (finalBacksideTexture) {
      uniforms.uBackTexture.value = finalBacksideTexture;
      if (finalBacksideTexture instanceof THREE.Texture) {
        uniforms.uBackRepeat.value.copy(finalBacksideTexture.repeat);
      }
    }
  }, [
    texture,
    finalBacksideTexture,
    backOffset,
    backScale,
    backClamp,
    color,
    frequency,
    amplitude,
    textSpeed,
    uniforms,
  ]);

  // ... inside Ribbon component

  // Track accumulated offset manually to handle variable speed
  const offsetRef = useRef(0);

  useFrame((state, delta) => {
    if (materialRef.current) {
      // uTime is scaled by `speed` (wave frequency)
      const time = state.clock.getElapsedTime() * speed;
      materialRef.current.uniforms.uTime.value = time;

      // Update accumulated offset
      // Base speed is 1.0 (accumulated over time), plus scroll velocity
      // Multiplier 2.0 makes scroll effect more pronounced
      const scrollInfluence = scrollVelocityRef.current * 2.0;

      // Accumulate: offset += (1 + scrollBoost) * delta
      // We adding 1.0 to represent the "base" flow of time
      offsetRef.current += (1.0 + scrollInfluence) * delta;

      materialRef.current.uniforms.uRunTime.value = offsetRef.current;
    }
  });

  return (
    <mesh position={position} ref={meshRef} rotation={rotation}>
      <boxGeometry args={[width, height, thickness, 256, 16, 1]} />
      <shaderMaterial
        fragmentShader={fragmentShader}
        ref={materialRef}
        side={THREE.DoubleSide}
        transparent
        uniforms={uniforms}
        vertexShader={vertexShader}
      />
    </mesh>
  );
};

export default Ribbon;

// Shared mutable state for scroll velocity
// Using a simple object ref avoids React Context overhead for high-frequency updates (60fps)
export const scrollVelocityRef = { current: 0 };

import { useThree } from "@react-three/fiber";
import { useEffect } from "react";
import * as THREE from "three";

/**
 * Adjusts the camera position based on the viewport width (responsiveness).
 * On mobile, we move the camera back so the ribbons fit better.
 */
export function useResponsiveCamera() {
  const { camera, size } = useThree();

  useEffect(() => {
    if (!(camera instanceof THREE.PerspectiveCamera)) {
      return;
    }

    // Simple breakpoint logic
    // If width < 768 (mobile/tablet portrait), move camera back
    const isMobile = size.width < 768;

    // Base Z position for desktop is 32 (from original code)
    // For mobile, we push it back significantly, e.g., 65
    const targetZ = isMobile ? 65 : 32;

    camera.position.setZ(targetZ);
    camera.updateProjectionMatrix();
  }, [camera, size.width]);
}

import { useTexture } from "@react-three/drei";
import { useMemo } from "react";
import {
  BACKSIDE_IMAGE_PATH,
  BACKSIDE_TEXT,
  RIBBON_BASE_HEIGHT,
  RIBBON_BASE_THICKNESS,
  RIBBON_COLORS,
  RIBBON_FONTS,
  RIBBON_IMAGE_ROWS,
  RIBBON_IMAGE_START_IDX,
  RIBBON_STRIP_COUNT,
  RIBBON_TEXT_SPEED_RANGE,
  RIBBON_TEXTS,
  RIBBON_VERTICAL_SPREAD,
  RIBBON_WAVE_SPEED_IMAGE_SECTION,
  RIBBON_WAVE_SPEED_MIN,
  RIBBON_WAVE_SPEED_VARIANCE,
  RIBBON_WIDTH,
} from "./constants";
import type { RibbonProps } from "./types";

export function useRibbons() {
  // We can call hooks conditionally here if we assume this component is always rendered the same way,
  // but better practice is to just use useTexture at top level.
  // However, since this is a custom hook intended for the component, it's fine.
  const dayjobTexture = useTexture(BACKSIDE_IMAGE_PATH);

  const ribbons = useMemo(() => {
    const totalHeight =
      RIBBON_STRIP_COUNT * (RIBBON_BASE_HEIGHT + RIBBON_VERTICAL_SPREAD);
    const startY = totalHeight / 2;
    const imageEndIdx = RIBBON_IMAGE_START_IDX + RIBBON_IMAGE_ROWS;

    return Array.from({ length: RIBBON_STRIP_COUNT }).map((_, i) => {
      const seedVal = i * 777.77;
      const random = (s: number) => {
        const x = Math.sin(s + seedVal) * 10_000;
        return x - Math.floor(x);
      };

      // Calculate precise Y to ensure no overlapping
      const y = startY - i * (RIBBON_BASE_HEIGHT + RIBBON_VERTICAL_SPREAD);

      const isInImageSection =
        i >= RIBBON_IMAGE_START_IDX - 1 && i < imageEndIdx;

      const xJitter = isInImageSection ? 0 : (random(3) - 0.5) * 4;
      const rotZ = isInImageSection ? 0 : (random(2) - 0.5) * 0.1;

      // Synchronize wave parameters for the image section so it moves like a single sheet
      const amplitude = isInImageSection ? 3.0 : 2.5 + random(5) * 1.0;
      const frequency = isInImageSection ? 0.04 : 0.03 + random(6) * 0.02;
      const speed = isInImageSection
        ? RIBBON_WAVE_SPEED_IMAGE_SECTION
        : RIBBON_WAVE_SPEED_MIN + random(4) * RIBBON_WAVE_SPEED_VARIANCE;

      // Subtle rotation and Z staggering to look like a "pile"
      // Subtle rotation and Z staggering to look like a "pile"
      const z = (random(1) - 0.5) * 2;

      // Use deterministic but scattered index to ensure ALL texts are shown
      // (i * 3) % length covers all indices since 3 is coprime to 8 (length)
      const textIndex = (i * 3) % RIBBON_TEXTS.length;
      const text = RIBBON_TEXTS[textIndex];

      // Backside Image Logic (Instagram feed style)
      let backsideImage = null;
      let backOffset: [number, number] = [0, 0];
      let backScale: [number, number] = [1, 1];
      let backClamp = 0.0;

      if (i >= RIBBON_IMAGE_START_IDX && i < imageEndIdx) {
        backsideImage = dayjobTexture;
        backClamp = 1.0;
        const rowIndex = i - RIBBON_IMAGE_START_IDX;

        // Total height the image spans in 3D units
        const totalImageHeight =
          RIBBON_IMAGE_ROWS * RIBBON_BASE_HEIGHT +
          (RIBBON_IMAGE_ROWS - 1) * RIBBON_VERTICAL_SPREAD;
        const imageAspect = 2624 / 1838; // 1.4276
        const totalImageWidth = totalImageHeight * imageAspect;

        // scaleX = ribbon_width / target_image_width
        const scaleX = RIBBON_WIDTH / totalImageWidth;
        const scaleY = RIBBON_BASE_HEIGHT / totalImageHeight;

        // No jitter anymore in image section, so offsetX is simpler
        const offsetX = 0.5 * (1 - scaleX);

        const offsetY =
          ((RIBBON_IMAGE_ROWS - 1 - rowIndex) *
            (RIBBON_BASE_HEIGHT + RIBBON_VERTICAL_SPREAD)) /
          totalImageHeight;

        backOffset = [offsetX, offsetY];
        backScale = [scaleX, scaleY];
      }

      const ribbon: RibbonProps = {
        text,
        subscript: text.includes("404") && i % 8 === 3 ? "4" : "",
        color: RIBBON_COLORS[i % RIBBON_COLORS.length],
        fontFamily: RIBBON_FONTS[0],
        position: [xJitter, y, z],
        rotation: [-0.08, 0, rotZ],
        speed,
        width: RIBBON_WIDTH,
        height: RIBBON_BASE_HEIGHT,
        thickness: RIBBON_BASE_THICKNESS,
        amplitude,
        frequency,
        fontWeight: "900",
        padding: 120,
        seed: seedVal,
        backsideText: BACKSIDE_TEXT,
        backsideImage,
        backOffset,
        backScale,
        backClamp,
        textSpeed: (random(7) - 0.5) * RIBBON_TEXT_SPEED_RANGE,
      };

      return ribbon;
    });
  }, [dayjobTexture]);

  return ribbons;
}

export const RIBBON_STRIP_COUNT = 35;
export const RIBBON_BASE_HEIGHT = 4.0;
export const RIBBON_BASE_THICKNESS = 4.0;
export const RIBBON_VERTICAL_SPREAD = 0.65;
export const RIBBON_IMAGE_START_IDX = 12;
export const RIBBON_IMAGE_ROWS = 10;
export const RIBBON_WIDTH = 220;

export const RIBBON_COLORS = [
  "#E6DDB5", // Muted Parchment
  "#DCCCA3", // Aged Tape
  "#E8DFC5", // Pale Beige
  "#D4C596", // Dull Yellow
  "#A63D3A", // Muted Brick Red (Accent)
  "#C8B88A", // Greyish Gold
];

export const RIBBON_FONTS = ["Inter, sans-serif", "system-ui, sans-serif"];

export const RIBBON_TEXTS = [
  "404 NOT FOUND",
  "PAGE NOT FOUND",
  "ERROR 404",
  "NOT FOUND",
  "404",
  "SYSTEM ERROR",
  "LOST IN SPACE",
  "NOT FOUND 404",
];

export const BACKSIDE_TEXT = "INSPIRED BY DAY JOB";
export const BACKSIDE_IMAGE_PATH = "https://www.razisyed.cv/experiments/404-not-found/dayjob.png";

// Animation Constants
export const RIBBON_TEXT_SPEED_RANGE = 6.0;
export const RIBBON_TEXT_SPEED_MULTIPLIER = 0.05;

export const RIBBON_WAVE_SPEED_MIN = 0.01;
export const RIBBON_WAVE_SPEED_VARIANCE = 0.015;
export const RIBBON_WAVE_SPEED_IMAGE_SECTION = 0.015;

export const vertexShader = `
uniform float uTime;
uniform float uFrequency;
uniform float uAmplitude;

varying vec2 vUv;
varying vec3 vNormal;
varying vec3 vWorldPosition;
varying vec3 vModelNormal;
varying float vIndent;

void main() {
  vUv = uv;
  vModelNormal = normal;

  vec3 newPosition = position;

  // Position-based offset for variety between ribbons
  float xPos = position.x * uFrequency + uTime;

  // Main curve - only in Z (depth) to prevent vertical clipping
  float indent = sin(xPos) * uAmplitude;

  // Add some layered noise/harmonics for paper-like character
  indent += sin(xPos * 2.1 + 0.4) * uAmplitude * 0.3;
  indent += sin(xPos * 4.4 + 1.2) * uAmplitude * 0.1;

  newPosition.z += indent;

  vIndent = indent;
  vNormal = normalize(normalMatrix * normal);
  vWorldPosition = (modelMatrix * vec4(newPosition, 1.0)).xyz;

  gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
}
`;

export const fragmentShader = `
uniform sampler2D uTexture;
uniform sampler2D uBackTexture;
uniform vec2 uBackOffset;
uniform vec2 uBackScale;
uniform float uOpacity;
uniform float uTime;
uniform float uRunTime;
uniform vec3 uColor;
uniform vec2 uRepeat;
uniform vec2 uBackRepeat;
uniform float uBackClamp;
uniform float uTextSpeed;

varying vec2 vUv;
varying vec3 vNormal;
varying vec3 vWorldPosition;
varying vec3 vModelNormal;
varying float vIndent;

float random(vec2 co) {
    return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
  vec3 normal = normalize(vNormal);
  vec3 viewDir = normalize(cameraPosition - vWorldPosition);

  vec4 texColor;

  // Front face is positive Z model normal, back face is negative Z
  if (vModelNormal.z > 0.5) {
      // Scroll the text using independent scroll time
      // uTextSpeed is now pre-multiplied by JS
      float scrollOffset = uRunTime * uTextSpeed;
      vec2 tiledUv = vUv * uRepeat + vec2(scrollOffset, 0.0);
      vec4 sampleCol = texture2D(uTexture, tiledUv);

      // Composite: Texture (Text/Lines) over Background (uColor)
      texColor = vec4(mix(uColor, sampleCol.rgb, sampleCol.a), 1.0);

  } else if (vModelNormal.z < -0.5) {
      // Use normal UV for the back side
      vec2 backUv;

      if (uBackClamp > 0.5) {
          // Clamped/Masked Image (Instagram feed style)
          backUv = vec2(vUv.x, vUv.y) * uBackScale + uBackOffset;
          if (backUv.x >= 0.0 && backUv.x <= 1.0 && backUv.y >= 0.0 && backUv.y <= 1.0) {
              texColor = texture2D(uBackTexture, backUv);
          } else {
              texColor = vec4(uColor, 1.0);
          }
      } else {
          // Repeating Text (Backside)
          backUv = vUv * uBackRepeat;
          vec4 sampleCol = texture2D(uBackTexture, backUv);
          texColor = vec4(mix(uColor, sampleCol.rgb, sampleCol.a), 1.0);
      }
  } else {
      texColor = vec4(uColor, 1.0);
  }

  // Lighting setup - matching mockup's warm, directional light
  // Key light: From top-right, more front-facing to fix darkness
  vec3 lightDir1 = normalize(vec3(0.5, 0.8, 0.8));
  float diff1 = max(dot(normal, lightDir1), 0.0);

  // Subtle fill from bottom-left
  vec3 lightDir2 = normalize(vec3(-0.5, -0.2, 0.4));
  float diff2 = max(dot(normal, lightDir2), 0.0) * 0.3;

  // Specular Reflection (the "nice reflection" the user likes)
  vec3 halfDir = normalize(lightDir1 + viewDir);
  float spec = pow(max(dot(normal, halfDir), 0.0), 32.0) * 0.4;

  vec3 faceColor = texColor.rgb;

  // Deepening shadows in "valleys"
  float shadow = smoothstep(1.0, -1.0, vIndent);
  shadow = mix(0.6, 1.0, shadow);

  // Ambient occlusion simulation
  float edgeAO = smoothstep(0.0, 0.12, vUv.y) * smoothstep(1.0, 0.88, vUv.y);
  edgeAO = mix(0.7, 1.0, edgeAO);

  // Rim lighting
  float rim = 1.0 - max(dot(viewDir, normal), 0.0);
  rim = pow(rim, 6.0) * 0.25;

  // High-frequency Grain
  float grain = (random(vUv * 100.0 + uTime * 0.001) - 0.5) * 0.03;

  vec3 finalColor = faceColor;

  // Apply lighting: Key + Fill + Spec + Shadow + EdgeAO + Rim
  finalColor *= (diff1 * 0.8 + diff2 + 0.25);
  finalColor *= shadow;
  finalColor *= edgeAO;

  // Add Specular and Rim on top
  finalColor += spec * vec3(1.0, 0.95, 0.8) * diff1; // Warm specular tied to key light
  finalColor += rim * vec3(1.0, 0.98, 0.95);
  finalColor += grain;

  gl_FragColor = vec4(finalColor, uOpacity * texColor.a);
}
`;

import type * as THREE from "three";

export interface RibbonProps {
  amplitude?: number;
  backClamp?: number;
  backOffset?: [number, number];
  backScale?: [number, number];
  backsideImage?: THREE.Texture | null;
  backsideText?: string;
  color: string;
  fontFamily?: string;
  fontWeight?: string;
  frequency?: number;
  height?: number;
  padding?: number;
  position: [number, number, number];
  rotation: [number, number, number];
  seed?: number;
  speed?: number;
  subscript?: string;
  text: string;
  textSpeed?: number;
  thickness?: number;
  width?: number;
}

import React, { useEffect } from "react";
import type * as THREE from "three";

// Global cache for texture sharing across instances
// Map key -> { texture, refCount }
const textureCache = new Map<
  string,
  { texture: THREE.CanvasTexture; refCount: number }
>();

type TextureGenerator = () => THREE.CanvasTexture | null;

export function useCachedTexture(
  key: string,
  generator: TextureGenerator
): THREE.CanvasTexture | null {
  // 1. Synchronously get or create texture
  const texture = React.useMemo(() => {
    if (!key) {
      return null;
    }

    const cachedItem = textureCache.get(key);

    if (cachedItem) {
      // Found in cache
      return cachedItem.texture;
    }
    // Not in cache, generate immediately
    const newTexture = generator();
    if (newTexture) {
      textureCache.set(key, { texture: newTexture, refCount: 0 }); // refCount init at 0, will increment in effect
      return newTexture;
    }
    return null;
    // We do NOT include dependencies here because the 'key' should already include all dependencies encoded in the string.
    // If we included dependencies, useMemo might re-run even if key is same, which is not what we want for a global cache.
    // The generator is called only when key changes or cache misses.
  }, [key, generator]);

  // 2. Manage ref counting and memory disposal via effect
  useEffect(() => {
    if (!(key && texture)) {
      return;
    }

    const item = textureCache.get(key);
    if (item) {
      item.refCount++;
    }

    return () => {
      const currentItem = textureCache.get(key);
      if (currentItem) {
        currentItem.refCount--;
        if (currentItem.refCount <= 0) {
          currentItem.texture.dispose();
          textureCache.delete(key);
        }
      }
    };
  }, [key, texture]);

  return texture;
}

import { useEffect, useState } from "react";

export function useFontsReady() {
  const [ready, setReady] = useState(false);

  useEffect(() => {
    document.fonts.ready.then(() => {
      setReady(true);
    });
  }, []);

  return ready;
}

import * as THREE from "three";

export interface FrontTextureParams {
  color: string;
  fontsReady: boolean;
  height: number;
  padding: number;
  subscript: string;
  text: string;
  width: number;
}

export interface BackTextureParams {
  color: string;
  fontsReady: boolean;
  height: number;
  text?: string;
  width: number;
}

export const generateFrontTexture = ({
  text,
  subscript,
  // color, // Removed as unused
  width,
  height,
  padding,
}: FrontTextureParams): THREE.CanvasTexture | null => {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) {
    return null;
  }

  const canvasHeight = 256;
  ctx.font = `900 ${canvasHeight * 0.6}px "Inter", "Arial Black", sans-serif`;
  const textMetrics = ctx.measureText(text);
  const textWidth = textMetrics.width;

  let totalTextWidth = textWidth;
  if (subscript) {
    ctx.font = `900 ${canvasHeight * 0.3}px "Inter", "Arial Black", sans-serif`;
    totalTextWidth += ctx.measureText(subscript).width + 8;
  }

  const unitWidth = totalTextWidth + padding * 2;
  const canvasWidth = unitWidth;

  canvas.width = canvasWidth;
  canvas.height = canvasHeight;

  // Draw background - TRANSPARENT
  ctx.clearRect(0, 0, canvasWidth, canvasHeight);

  // Draw red guide lines
  ctx.strokeStyle = "#be123c";
  ctx.lineWidth = 6;
  ctx.globalAlpha = 0.8;
  ctx.beginPath();
  ctx.moveTo(0, canvasHeight * 0.18);
  ctx.lineTo(canvasWidth, canvasHeight * 0.18);
  ctx.moveTo(0, canvasHeight * 0.82);
  ctx.lineTo(canvasWidth, canvasHeight * 0.82);
  ctx.stroke();
  ctx.globalAlpha = 1.0;

  // Draw text
  ctx.font = `900 ${canvasHeight * 0.6}px "Inter", "Arial Black", sans-serif`;
  ctx.fillStyle = "#0c0c0c";
  ctx.textAlign = "left";
  ctx.textBaseline = "middle";
  ctx.letterSpacing = "-2px";
  ctx.fillText(text, padding, canvasHeight * 0.52);

  if (subscript) {
    ctx.font = `900 ${canvasHeight * 0.3}px "Inter", "Arial Black", sans-serif`;
    ctx.fillText(subscript, padding + textWidth - 4, canvasHeight * 0.65);
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;

  const unitAspect = unitWidth / canvasHeight;
  const geomAspect = width / height;
  tex.repeat.set(geomAspect / unitAspect, 1);

  tex.anisotropy = 16;
  return tex;
};

export const generateBackTexture = ({
  text,
  // color, // Unused
  width,
  height,
}: BackTextureParams): THREE.CanvasTexture | null => {
  // If no specifically provided text, we still want the "INSPIRED BY" repeating
  const baseBackText = text || "INSPIRED BY DAY JOB";

  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) {
    return null;
  }

  const canvasHeight = 256;
  // Match front side style but maybe different font variant
  ctx.font = `italic 900 ${canvasHeight * 0.45}px "Inter", "system-ui", sans-serif`;
  const textWidth = ctx.measureText(baseBackText).width;

  const backPadding = 120; // Nice loose spacing for repetition
  const unitWidth = textWidth + backPadding * 2;

  canvas.width = unitWidth;
  canvas.height = canvasHeight;

  // Transparent background, color handled in shader
  ctx.clearRect(0, 0, unitWidth, canvasHeight);

  // Guide lines
  ctx.strokeStyle = "#be123c";
  ctx.lineWidth = 6;
  ctx.globalAlpha = 0.8;
  ctx.beginPath();
  ctx.moveTo(0, canvasHeight * 0.18);
  ctx.lineTo(unitWidth, canvasHeight * 0.18);
  ctx.moveTo(0, canvasHeight * 0.82);
  ctx.lineTo(unitWidth, canvasHeight * 0.82);
  ctx.stroke();
  ctx.globalAlpha = 1.0;

  // Text
  ctx.font = `italic 900 ${canvasHeight * 0.45}px "Inter", "system-ui", sans-serif`;
  ctx.fillStyle = "#0c0c0c";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(baseBackText, unitWidth / 2, canvasHeight * 0.52);

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;

  // Calculate repeat for text mode
  const unitAspect = unitWidth / canvasHeight;
  const geomAspect = width / height;
  tex.repeat.set(geomAspect / unitAspect, 1);

  return tex;
};
